package org;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Scanner;
import java.util.TreeMap;
import java.util.regex.Pattern;
import org.commands.SaveCommand;
import org.dataclasses.*;
import org.dataclasses.enums.*;

public class App {

    private static String fileName;
    private static TreeMap<Integer, Movie> collection = new TreeMap<>();

    public static String getStorageFile() {
        return App.fileName;
    }

    public static TreeMap<Integer, Movie> getCollection() {
        return collection;
    }

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println(
                "Usage: java -jar /path/to/.jar /path/to/inputfile.xml"
            );
            System.exit(1);
        }
        fileName = args[0];
        try (
            InputStream inputStream = Files.newInputStream(Paths.get(fileName))
        ) {
            while (inputStream.available() > 0) {
                byte input[] = inputStream.readAllBytes();
                System.out.println(new String(input));
            }
        } catch (IOException e) {
            System.out.println(e.toString());
        }
        Location operatorLocation = new Location(515074L, -0.1278, "London");
        Person movieOperator = new Person(
            "Christopher Nolan",
            78.5,
            "PASSPORT98765",
            Country.CHINA,
            operatorLocation
        );
        Coordinates movieCoordinates = new Coordinates(150, 350);

        Movie testMovie = new Movie(
            "Inception",
            movieCoordinates,
            4, // oscarsCount > 0
            MovieGenre.ADVENTURE,
            MpaaRating.PG_13,
            movieOperator
        );
        collection.put(testMovie.getID(), testMovie);
        SaveCommand.exec();
        Pattern pattern = Pattern.compile(
            "<Movie.*?>.*?</Movie>",
            Pattern.DOTALL
        );

        try (Scanner scanner = new Scanner(new File("./testfile"), "UTF-8")) {
            while (scanner.findWithinHorizon(pattern, 0) != null) {
                Movie testmovie2 = Movie.fromXML(scanner.match().group(0));
                collection.put(testmovie2.getID(), testmovie2);
            }
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
